package com.bankScraper.bank

import com.bankScraper.Enums
import com.bankScraper.RequestQueue

class ProcessedBankStatementVO {

    BankCredentialCO bankCredentialCO
    ProcessBankStatementCO processBankStatementCO
    BasicDetailsResponse basicDetails
    List<BankTransactionResponse> bankTransactionList
    BankStatementStatusResponse statementStatus
    List<RequestQueue> requestQueueList = []
    Long totalTime
    Boolean isBasicDetailsParsed = Boolean.FALSE
    Boolean isTransactionDataInconsistent = Boolean.FALSE

    ProcessedBankStatementVO() {}

    ProcessedBankStatementVO(ProcessBankStatementCO processBankStatementCO) {
        this.processBankStatementCO = processBankStatementCO
        this.basicDetails = new BasicDetailsResponse()
        this.bankTransactionList = []
        this.statementStatus = new BankStatementStatusResponse()
    }

    public ProcessedBankStatementVO(BankCredentialCO bankCredentialCO) {
        this.bankCredentialCO =<REDACTED>
        this.basicDetails = new BasicDetailsResponse()
        this.bankTransactionList = []
        this.statementStatus = new BankStatementStatusResponse()
    }

    ProcessedBankStatementVO(List<BankTransactionResponse> bankTransactionResponseList, Enums.Bank bank, String salaryKeyword) {
