package com.bankScraper.bank

import com.bankScraper.AppUtil
import com.bankScraper.Enums
import com.bankScraper.HelperMethod
import com.bankScraper.person.Client
import grails.validation.Validateable

import javax.servlet.http.HttpServletRequest

@Validateable
class ProcessBankStatementCO {
    String uniqueId = AppUtil.getUniqueStr()
    String bank
    String accountType
    File bankStatement
    String contentType
    String password
    String oDLimit
    String accountUID
    String employerDetails
    File textFile
    String fileName
    Client client
    Enums.StatementParsingType parsingType = Enums.StatementParsingType.NEW
    Map paramsMap
    List<String> accountUIDList = []

    static constraints = {
        bank nullable: false, blank: false, validator: { val, obj ->
            if (!(val in Enums.Bank.values()*.name()))
                return 'processBankStatementCO.bank.not.supported'
        }
        accountType nullable: false
        contentType nullable: false
        bankStatement nullable: false, validator: { val, obj ->
            if (val.size() == 0) {
                return 'processBankStatementCO.document.not.uploaded'
            } else {
                if (!(HelperMethod.getContentTypeOfFile(val, obj.password) in ["application/pdf"])) {         //TODO
                    return 'processBankStatementCO.document.not.supported'
                }
            }
        }
        password blank: true, nullable: true, validator: { val, obj ->
            if (obj.bankStatement && obj.bankStatement.bytes)
                obj.password =<REDACTED>
            true
        }
        oDLimit blank: true, nullable: true
        accountUID blank: true, nullable: true
        employerDetails blank: true, nullable: true
        textFile nullable: true
        uniqueId nullable: false
        fileName nullable: false
        client blank: true, nullable: true
        paramsMap nullable: true
    }

    ProcessBankStatementCO() {}

    ProcessBankStatementCO(HttpServletRequest requestObject, File file, Client client, String fileName = "") {
        this.bankStatement = file
        this.bank = requestObject.getParameter("bank")
        this.password =<REDACTED>
        this.contentType = HelperMethod.getContentTypeOfFile(file, this.password)
        this.accountType = requestObject.getParameter("accountType")
        this.employerDetails = requestObject.getParameter("employerDetails")
        this.accountUID = requestObject.getParameter("accountUID")
        this.oDLimit = requestObject.getParameter("oDLimit")
        this.fileName = fileName ?: file.name
        this.client = client
    }

    ProcessBankStatementCO(def mapParams, Client client) {
        String fileName = mapParams.bankStmtFile ? mapParams.bankStmtFile.originalFilename : mapParams.bankStmt.originalFilename
        this.bankStatement = HelperMethod.convertMultipartFileToFile(mapParams.bankStmtFile ?: mapParams.bankStmt)
        this.bank = mapParams.bank
        this.password =<REDACTED>
        this.contentType = HelperMethod.getContentTypeOfFile(this.bankStatement, this.password)
        this.accountType = mapParams.accountType
        this.employerDetails = mapParams.employerDetails
        this.accountUID = mapParams.accountUID
        this.oDLimit = mapParams.oDLimit
        this.fileName = fileName
        this.client = client
        this.paramsMap = mapParams
    }

    ProcessBankStatementCO(String bank, String salaryKeyword) {
        this.bank = bank
        this.employerDetails = salaryKeyword
    }

    ProcessBankStatementCO(File file, BankAccount bankAccount, BankStatement bankStatement, Client client, Enums.StatementParsingType parsingType) {
        this.bankStatement = file
        this.bank = bankAccount.bank
        this.accountType = bankAccount.accountType in [Enums.AccountType.OVER_DRAFT] ? Enums.AccountType.CURRENT.name() : bankAccount.accountType.name()
        this.password =<REDACTED>
        this.contentType = HelperMethod.getContentTypeOfFile(this.bankStatement, this.password)
        this.employerDetails = bankAccount.salaryKeyword
        this.oDLimit = bankAccount.accountLimit ? String.valueOf(bankAccount.accountLimit) : null
        this.fileName = file.name
        this.client = client
        this.parsingType = parsingType
        this.textFile = HelperMethod.convertPDFToText(file.bytes, this.password)
    }

    ProcessBankStatementCO(BankCredentialCO bankCredentialCO) {
        this.bank = bankCredentialCO.bank
        this.employerDetails = bankCredentialCO.employerDetails
    }
}


