package com.bankScraper

class Enums {
    enum BankTransactionType {
        CREDIT, DEBIT
    }

    enum StatementParsedStatus {
        PARTIALLY_PARSED, TRANSACTION_PARTIALLY_PARSED, ERROR, CORRUPT_FILE, SCANNED_FILE, UNSUPPORTED_FILE, CATEGORISED
    }

    enum TransactionDataType {
        ORDINARY
    }

    enum Bank {
        ANDHRA_BANK, BANK_OF_BARODA, CITY_UNION, HSBC, KARUR_VYASA, KOTAK, ORIENTAL_BANK, PNB
    }
}

class AppUtil {
    static String getUniqueStr() {
        UUID.randomUUID().toString()
    }

    static String getStackTraceAsString(Exception e) {
        StringWriter writer = new StringWriter()
        e.printStackTrace(new PrintWriter(writer))
        writer.toString()
    }
}

class HelperMethod {
    static Double getSanitizeDouble(String value) {
        if (!value) {
            return 0d
        }
        String sanitized = value.replaceAll("[^0-9.\\-]", "")
        if (!sanitized || sanitized == "-" || sanitized == ".") {
            return 0d
        }
        try {
            return Double.valueOf(sanitized)
        } catch (Exception e) {
            return 0d
        }
    }

    static BigDecimal roundTo2Places(def value) {
        value == null ? null : new BigDecimal(value.toString()).setScale(2, BigDecimal.ROUND_HALF_UP)
    }
}

class LogEntry {
    static void debug(String message) { println(message) }

    static void error(String message, Exception e = null) { println(message) }
}

