}

class BankStatementStatusResponse {
    Enums.StatementParsedStatus statementParsedStatus
    String exceptionStackTrace
    String message
}

class ProcessBankStatementCO {
    String bank
    File bankStatement
    String password
    File textFile
}

class ProcessedBankStatementVO {
    ProcessBankStatementCO processBankStatementCO
    BasicDetailsResponse basicDetails
    List<BankTransactionResponse> bankTransactionList
    BankStatementStatusResponse statementStatus

    ProcessedBankStatementVO() {
        this.processBankStatementCO = new ProcessBankStatementCO()
        this.basicDetails = new BasicDetailsResponse()
        this.bankTransactionList = []
        this.statementStatus = new BankStatementStatusResponse()
    }
}

class BankUtil {

    static Double processBalanceAmount(String balanceString) {
        Double balanceDouble = 0
        balanceString = balanceString.toLowerCase()
        if (balanceString && balanceString.trim())
            balanceDouble = HelperMethod.getSanitizeDouble(balanceString.replaceAll("dr.|cr.|dr|cr|db|cb|c|\\s", ""))
        if (balanceString.find("d"))
            balanceDouble = -balanceDouble
        balanceDouble
    }

    static BankTransactionResponse createOpeningBalanceTransaction(Double openingBalance) {
        BankTransactionResponse openingBalanceTransaction = new BankTransactionResponse()
        openingBalanceTransaction.description = "OPENING BALANCE"
        openingBalanceTransaction.type = Enums.BankTransactionType.CREDIT
        openingBalanceTransaction.amount = openingBalance
        openingBalanceTransaction.balanceAfterTransaction = openingBalance as BigDecimal
        openingBalanceTransaction
    }

    static BankTransactionResponse findOpeningBalanceTransaction(BankTransactionResponse firstTransaction,
                                                                 BankTransactionResponse lastTransaction) {
        BankTransactionResponse initialTransaction = firstTransaction.transactionDate <= lastTransaction.transactionDate ?
                firstTransaction : lastTransaction
        Double openingBalance = initialTransaction.type == Enums.BankTransactionType.DEBIT ?
                initialTransaction.balanceAfterTransaction + initialTransaction.amount :
                initialTransaction.balanceAfterTransaction - initialTransaction.amount
        BankTransactionResponse openingBalanceTransaction = createOpeningBalanceTransaction(openingBalance)
        openingBalanceTransaction.transactionDate = initialTransaction.transactionDate
        openingBalanceTransaction.valueDate = initialTransaction.valueDate ?: initialTransaction.transactionDate
        openingBalanceTransaction
    }

    static void checkForOpeningBalanceTransaction(List<BankTransactionResponse> bankTransactionList, Date fromDate) {
        if (bankTransactionList.first().description != "OPENING BALANCE") {
            BankTransactionResponse openingBalanceTransaction =
                    findOpeningBalanceTransaction(bankTransactionList.first(), bankTransactionList.last())
            openingBalanceTransaction.transactionDate = fromDate && fromDate < openingBalanceTransaction.transactionDate ?
                    fromDate : openingBalanceTransaction.transactionDate
            bankTransactionList.add(0, openingBalanceTransaction)
        } else if (!bankTransactionList.first().transactionDate) {
            bankTransactionList.first().transactionDate = (bankTransactionList.get(1).transactionDate < bankTransactionList.last().transactionDate) ?
                    bankTransactionList.get(1).transactionDate : bankTransactionList.last().transactionDate
        }
    }

    static void findFromAndToDate(BankTransactionResponse firstTransaction, BankTransactionResponse lastTransaction,
                                  BasicDetailsResponse basicDetails) {
        Calendar firstTransactionDate = firstTransaction.transactionDate.toCalendar()
        Calendar lastTransactionDate = lastTransaction.transactionDate.toCalendar()
        if (!basicDetails?.fromDate || !basicDetails?.toDate) {
            if (firstTransactionDate < lastTransactionDate) {
                basicDetails.fromDate = firstTransactionDate
                basicDetails.toDate = lastTransactionDate
            } else {
                basicDetails.fromDate = lastTransactionDate
                basicDetails.toDate = firstTransactionDate
            }
        }
    }

    static List<BankTransactionResponse> sortBankTransactions(List<BankTransactionResponse> bankTransactionList) {
        bankTransactionList.sort { it.transactionDate }
    }

    static void addCreditOrDebitAndBalanceForTransaction(ProcessedBankStatementVO processedBankStatementVO) {
        List<BankTransactionResponse> bankTransactionList = processedBankStatementVO.bankTransactionList
        BankTransactionResponse bankTransactionResponse = bankTransactionList.remove(0)
        if (bankTransactionList.first().transactionDate.compareTo(bankTransactionList.last().transactionDate) > 0) {
            bankTransactionList = bankTransactionList.reverse()
        }
        bankTransactionList.add(0, bankTransactionResponse)
        for (int i = 1; i < bankTransactionList.size(); i++) {
            bankTransactionResponse = bankTransactionList.get(i)
            if (bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction != null && bankTransactionResponse.balanceAfterTransaction > bankTransactionList.get(i - 1).balanceAfterTransaction) {
                bankTransactionList.get(i).amount = bankTransactionResponse.balanceAfterTransaction - bankTransactionList.get(i - 1).balanceAfterTransaction
                bankTransactionList.get(i).type = Enums.BankTransactionType.CREDIT
            } else if (bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction != null && bankTransactionResponse.balanceAfterTransaction < bankTransactionList.get(i - 1).balanceAfterTransaction) {
                bankTransactionList.get(i).amount = bankTransactionList.get(i - 1).balanceAfterTransaction - bankTransactionResponse.balanceAfterTransaction
                bankTransactionList.get(i).type = Enums.BankTransactionType.DEBIT
            } else if ((bankTransactionResponse.amount == null && bankTransactionResponse.balanceAfterTransaction == null) || (bankTransactionResponse.amount == 0D && bankTransactionResponse.balanceAfterTransaction == 0.00)) {
                bankTransactionList.get(i).amount = 0
                bankTransactionList.get(i).type = Enums.BankTransactionType.CREDIT
                bankTransactionList.get(i).balanceAfterTransaction = bankTransactionList.get(i - 1).balanceAfterTransaction
            } else if (bankTransactionResponse.amount != null && (bankTransactionResponse.balanceAfterTransaction == 0.00 || bankTransactionResponse.balanceAfterTransaction == null)) {
                bankTransactionList.get(i).balanceAfterTransaction = bankTransactionResponse.type == Enums.BankTransactionType.DEBIT ?
                        bankTransactionList.get(i - 1).balanceAfterTransaction - bankTransactionResponse.amount :
                        bankTransactionList.get(i - 1).balanceAfterTransaction + bankTransactionResponse.amount
            }
        }
        processedBankStatementVO.bankTransactionList = bankTransactionList
    }
}

