/**
 * Removes every '-', '/' and space used as a separator inside a date having a month name in it and fixes the
 * known OCR mistakes done for the month names.  eg: '03- JUL- 2017' and '03-JUY-2017' both become '03JUL2017'
 */
public static String normalizeMonthNameDate(String dateValue) {
    dateValue = dateValue.replaceAll("[\\s]", "").replaceAll("-", "").replaceAll("/", "").trim()
    dateValue = dateValue.replaceAll("(?i)JUY", "JUL")
