        List<IncomeVO> incomeVOList = []
        List<BankTransactionResponse> salaryTransactions = transactionList.findAll {
            it.transactionCategory == BankTransactionCategory.SALARY || it.transactionSubcategory == BankTransactionSubcategory.SALARY
        }
        salaryTransactions.each { transaction ->
            Boolean isSalaryCheck = publicHolidaysService.checkPublicHoliday(transaction.transactionDate)
            incomeVOList << new IncomeVO(transaction, isSalaryCheck)
