            }
        }
        monthWiseExpenseVOList
    }

    public Double fetchAverageExpensePerMonth(List<BankTransactionResponse> transactionList) {
        Double avgExpense = 0.00
        List<ExpenseVO> expenseVOList = fetchExpenseInstances(transactionList)
        if (expenseVOList) {
            List<Date> noOfMonths = DateUtil.getDatesOfMonthsBetweenTwoDates(expenseVOList.first().date, expenseVOList.last().date)
            println "**** No of Months between the date range for Expense : ${noOfMonths.size()}"
            Double totalExpense = expenseVOList*.amount.sum()
            if (totalExpense) {
                avgExpense = totalExpense / noOfMonths.size()
                println " ==== Total Expense : ${totalExpense} and Monthly Expense : ${avgExpense}"
            }
        }
        return avgExpense
    }

