+    public
+    static Date parseTransactionDate(String date, List<BankTransactionResponse> bankTransactionList) {
+        try {
+            return dateFormatFromString(date).parse(date)
+        } catch (Exception e) {
+            return bankTransactionList ? bankTransactionList.last().transactionDate : null
+        }
+    }
