public static BankTransactionHeaderIndex headerIndex(Element element) {
    BankTransactionHeaderIndex bankTransactionHeaderIndex = new BankTransactionHeaderIndex()
    Map<String, String> headerMap = headerDictionary()
    Elements headerElements = rowElements(element)
    for (int i = 0; i < headerElements.size(); i++) {
        if (headerElements.eq(i).text().trim().find(headerMap.date) && bankTransactionHeaderIndex.transactionDateIndex == null)
            bankTransactionHeaderIndex.transactionDateIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.value_date))
            bankTransactionHeaderIndex.valueDateIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.cheque_no))
            bankTransactionHeaderIndex.chequeNoIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.description))
            bankTransactionHeaderIndex.descriptionIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.balance_after_transaction))
            bankTransactionHeaderIndex.balanceAfterTransactionIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.amount_type))
            bankTransactionHeaderIndex.amountTypeIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.debit))
            bankTransactionHeaderIndex.debitIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.credit))
            bankTransactionHeaderIndex.creditIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.amount))
            bankTransactionHeaderIndex.amountIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.branch_code))
            bankTransactionHeaderIndex.branchCodeIndex = i
        else if (headerElements.eq(i).text().trim().find(headerMap.instrument_id))
            bankTransactionHeaderIndex.instrumentIndex = i
    }
    return bankTransactionHeaderIndex
}

