/**
 * Cells of a row of the transaction table. The header row of a few statements is built out of 'th' cells.
 */
public static Elements rowCells(Element element) {
    element.select("td, th")
}

/**
 * Fetches the text of a column of a transaction row. Statements do have rows having less columns than the
 * header row, hence the column is fetched only if it is really present in the row.
 */
public static String cellValue(Elements rowElements, Integer columnIndex) {
    (columnIndex != null && columnIndex >= 0 && rowElements.size() > columnIndex) ? rowElements.eq(columnIndex).text() : ""
}

/**
 * The transaction header row gets repeated in between the transactions of multi page statements, such rows
 * along with the total/tally rows are not transactions.
 */
public static Boolean isJunkTransactionRow(String date, String description) {
    Map<String, String> headerMap = headerDictionary()
    Boolean isJunkRow = date && date.trim().find(headerMap.junk_date)
    isJunkRow || (description && description.trim().find(headerMap.junk_date))
}

/**
 * Opening balance row of a statement is not a transaction, it only carries the balance the statement starts with.
 */
public static Boolean isBalanceBroughtForwardRow(String date, String description) {
    Map<String, String> headerMap = headerDictionary()
    Boolean isBroughtForwardRow = date && date.trim().find(headerMap.balance_brought_forward)
    isBroughtForwardRow || (description && description.trim().find(headerMap.balance_brought_forward))
}

/**
 * Parses the transaction date of a transaction row. A row not having a date of its own belongs to the date of
 * the transaction printed just above it.
 */
public
static Date parseTransactionDate(String date, List<BankTransactionResponse> bankTransactionList) {
    try {
        return dateFormatFromString(date).parse(date)
    } catch (Exception e) {
        return bankTransactionList ? bankTransactionList.last().transactionDate : null
    }
}

public static Date parseValueDate(String valueDate) {
    try {
        return valueDate ? dateFormatFromString(valueDate).parse(valueDate) : null
    } catch (Exception e) {
        return null
    }
}

/**
 * Assigns the reference, the debit or the credit direction, the amount and the running balance of a transaction
 * row, whichever of them the statement provides.
 */
public
static void assignAmountAndBalanceForTransaction(BankTransactionResponse bankTransactionResponse, Elements rowElements,
                                                 BankTransactionHeaderIndex bankTransactionHeaderIndex) {
    bankTransactionResponse.remark = cellValue(rowElements, bankTransactionHeaderIndex.chequeNoIndex)
    String balance = cellValue(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex)
    if (balance.trim()) {
        bankTransactionResponse.balanceAfterTransaction = BankUtil.processBalanceAmount(balance)
    }
    String debit = cellValue(rowElements, bankTransactionHeaderIndex.debitIndex)
    String credit = cellValue(rowElements, bankTransactionHeaderIndex.creditIndex)
    String amount = cellValue(rowElements, bankTransactionHeaderIndex.amountIndex)
    String amountType = cellValue(rowElements, bankTransactionHeaderIndex.amountTypeIndex)
    if (debit && !debit.find("^[\\s]*(-[\\s]*)?\$")) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(debit)
        bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
    }
    if (credit && !credit.find("^[\\s]*(-[\\s]*)?\$") && (!bankTransactionResponse.amount || bankTransactionResponse.amount == 0d)) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(credit)
        bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
    }
    if (amount && !amount.find("^[\\s]*(-[\\s]*)?\$")) {
        bankTransactionResponse.amount = HelperMethod.getSanitizeDouble(amount.replaceAll("(?i)[cd]r[.]?", ""))
        if (amount.toLowerCase().find("dr")) {
            bankTransactionResponse.type = Enums.BankTransactionType.DEBIT
        } else if (amount.toLowerCase().find("cr")) {
            bankTransactionResponse.type = Enums.BankTransactionType.CREDIT
        }
    }
    if (amountType.trim()) {
        bankTransactionResponse.type = amountType.toLowerCase().find("cr") ? Enums.BankTransactionType.CREDIT :
                Enums.BankTransactionType.DEBIT

    static void extractTransactionsFromHTMLHavingDescriptionAboveDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (cellValue(rowCells(elements.first()), bankTransactionHeaderIndex.transactionDateIndex).find("[A-z]{4,}")) {
                elements.remove(0)
            }
            Integer elementCount = elements.size()
            Integer lineCount = 0
            String description = ""
            while (lineCount < elementCount) {
                try {
                    Elements rowElements = rowCells(elements.get(lineCount))
                    String date = processValue(cellValue(rowElements, bankTransactionHeaderIndex.transactionDateIndex).trim())
                    String balance = cellValue(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex).trim()
                    String rowDescription = cellValue(rowElements, bankTransactionHeaderIndex.descriptionIndex)
                    if (isJunkTransactionRow(date, rowDescription) || isBalanceBroughtForwardRow(date, rowDescription)) {
                        lineCount += 1
                        continue
                    }
//                    A row carrying a balance is a transaction, even when the statement does not repeat the date on it.
                    if (balance && (date || processedBankStatementVO.bankTransactionList)) {
                        BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                        bankTransactionResponse.transactionDate = parseTransactionDate(date, processedBankStatementVO.bankTransactionList)
                        bankTransactionResponse.valueDate = parseValueDate(processValue(cellValue(rowElements, bankTransactionHeaderIndex.valueDateIndex).trim()))
                        description = description + " " + rowDescription
                        bankTransactionResponse.description = description.trim()
                        assignAmountAndBalanceForTransaction(bankTransactionResponse, rowElements, bankTransactionHeaderIndex)
                        if (bankTransactionResponse.transactionDate) {
                            processedBankStatementVO.bankTransactionList << bankTransactionResponse
                        }
                        description = ""
                    } else {
                        description = description + rowDescription
                    }
                } catch (Exception e) {
                    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                    processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                    processedBankStatementVO.statementStatus.message = "Exception occurred during parsing ${processedBankStatementVO.processBankStatementCO.bank} download statement 'HTMLHavingDescriptionAboveDate' ====>>>>>> ${e.message}"
                    log.error(processedBankStatementVO.statementStatus.message, e)
                }
                lineCount += 1
            }
        }
        if (processedBankStatementVO.bankTransactionList.size() != 0) {
            BankUtil.checkForOpeningBalanceTransaction(processedBankStatementVO.bankTransactionList,
                    processedBankStatementVO.basicDetails?.fromDate?.getTime())
            BankUtil.findFromAndToDate(processedBankStatementVO.bankTransactionList.first(),
                    processedBankStatementVO.bankTransactionList.last(), processedBankStatementVO.basicDetails)
            BankUtil.addCreditOrDebitAndBalanceForTransaction(processedBankStatementVO)
        }
    }

    public
    static void extractTransactionsFromHTMLHavingDescriptionBelowDate(ProcessedBankStatementVO processedBankStatementVO) {
        String result = PDF2Table.fetchTransactionHTML(processedBankStatementVO.processBankStatementCO.bankStatement, processedBankStatementVO.processBankStatementCO.password)
        JSONArray resultList = new JSONArray(result)
        for (int i = 0; i < resultList.length(); i++) {
            org.jsoup.nodes.Document jsoupDoc = Jsoup.parse(resultList.get(i).toString())
            Elements elements = jsoupDoc.select("tr")
            BankTransactionHeaderIndex bankTransactionHeaderIndex = headerIndex(elements.first())
            if (cellValue(rowCells(elements.first()), bankTransactionHeaderIndex.transactionDateIndex).find("[A-z]{4,}")) {
                elements.remove(0)
            }
            Integer elementCount = elements.size()
            Integer lineCount = 0
            while (lineCount < elementCount) {
                try {
                    Elements rowElements = rowCells(elements.get(lineCount))
                    String date = processValue(cellValue(rowElements, bankTransactionHeaderIndex.transactionDateIndex).trim())
                    String balance = cellValue(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex).trim()
                    String description = cellValue(rowElements, bankTransactionHeaderIndex.descriptionIndex)
//                    A row carrying a balance is a transaction, even when the statement does not repeat the date on it
//                    or leaves the description of it blank.
                    if (balance && (date || processedBankStatementVO.bankTransactionList) &&
                            !isJunkTransactionRow(date, description) && !isBalanceBroughtForwardRow(date, description)) {
                        BankTransactionResponse bankTransactionResponse = new BankTransactionResponse()
                        bankTransactionResponse.transactionDate = parseTransactionDate(date, processedBankStatementVO.bankTransactionList)
                        bankTransactionResponse.valueDate = parseValueDate(processValue(cellValue(rowElements, bankTransactionHeaderIndex.valueDateIndex).trim()))
//                        The description of a transaction gets printed on the rows following the row having the date on it.
                        while (lineCount + 1 < elementCount && isDescriptionContinuationRow(rowCells(elements.get(lineCount + 1)), bankTransactionHeaderIndex)) {
                            description = description + " " + cellValue(rowCells(elements.get(lineCount + 1)), bankTransactionHeaderIndex.descriptionIndex)
                            lineCount++
                        }
                        bankTransactionResponse.description = description.trim()
                        assignAmountAndBalanceForTransaction(bankTransactionResponse, rowElements, bankTransactionHeaderIndex)
                        if (bankTransactionResponse.transactionDate) {
                            processedBankStatementVO.bankTransactionList << bankTransactionResponse
                        }
                    }
                } catch (Exception e) {
                    log.error(elements.get(lineCount).text())
                    processedBankStatementVO.statementStatus.statementParsedStatus = Enums.StatementParsedStatus.TRANSACTION_PARTIALLY_PARSED
                    processedBankStatementVO.statementStatus.exceptionStackTrace = AppUtil.getStackTraceAsString(e)
                    processedBankStatementVO.statementStatus.message = "Exception occurred during parsing ${processedBankStatementVO.processBankStatementCO.bank} download statement 'HTMLHavingDescriptionBelowDate' ====>>>>>> ${e.message}"
                    log.error(processedBankStatementVO.statementStatus.message, e)
                }
                lineCount += 1
            }
        }
        if (processedBankStatementVO.bankTransactionList.size() != 0) {
            BankUtil.checkForOpeningBalanceTransaction(processedBankStatementVO.bankTransactionList,
                    processedBankStatementVO.basicDetails?.fromDate?.getTime())
            BankUtil.findFromAndToDate(processedBankStatementVO.bankTransactionList.first(),
                    processedBankStatementVO.bankTransactionList.last(), processedBankStatementVO.basicDetails)
            BankUtil.addCreditOrDebitAndBalanceForTransaction(processedBankStatementVO)
        }
    }

    /**
     * A row not having a date and a balance of its own only carries the remaining description of the transaction
     * printed above it.
     */
    public
    static Boolean isDescriptionContinuationRow(Elements rowElements, BankTransactionHeaderIndex bankTransactionHeaderIndex) {
        Map<String, String> headerMap = headerDictionary()
        String date = cellValue(rowElements, bankTransactionHeaderIndex.transactionDateIndex).trim()
        String description = cellValue(rowElements, bankTransactionHeaderIndex.descriptionIndex).trim()
        String balance = cellValue(rowElements, bankTransactionHeaderIndex.balanceAfterTransactionIndex).trim()
